/* prog49_bst.c
 *
 * Re‑implementation of the original binary (prog49_bst) based on the
 * decompiled control‑flow.  The program builds a binary‑search tree from
 * the command‑line arguments and prints one of three traversals:
 *
 *   ./prog49_bst in  5 3 7   -> inorder   (sorted order)
 *   ./prog49_bst pre 5 3 7   -> preorder
 *   ./prog49_bst post 5 3 7  -> postorder
 *
 * If the mode string is missing or not one of the three supported
 * strings, the program prints "INVALID_MODE".  If no numbers are given
 * (i.e. the tree stays empty) the program prints "EMPTY".  All output
 * lines are terminated by a newline.
 *
 * The implementation follows the same logical rules as the original
 * binary (duplicates are inserted to the right subtree, a maximum of
 * 64 nodes is enforced – the original silently ignored excess nodes,
 * but this re‑implementation simply stops inserting them).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64          /* matches the original’s 0x3f limit */

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

/* Global pool of nodes – the original binary used a static array. */
static Node node_pool[MAX_NODES];
static int  used_nodes = 0;

/* Allocate a new node from the pool. Returns NULL if the pool is exhausted. */
static Node *new_node(long v)
{
    if (used_nodes >= MAX_NODES)
        return NULL;               /* original silently ignored extra nodes */
    Node *n = &node_pool[used_nodes++];
    n->value = v;
    n->left = n->right = NULL;
    return n;
}

/* Insert a value into the BST.  Duplicates go to the right subtree,
   exactly as the original binary does. */
static void bst_insert(Node **root, long v)
{
    if (*root == NULL) {
        *root = new_node(v);
        return;
    }

    Node *cur = *root;
    while (1) {
        if (v < cur->value) {
            if (cur->left == NULL) {
                cur->left = new_node(v);
                return;
            }
            cur = cur->left;
        } else {                     /* v >= cur->value : duplicates to right */
            if (cur->right == NULL) {
                cur->right = new_node(v);
                return;
            }
            cur = cur->right;
        }
    }
}

/* Helper for printing a space before every value except the first one. */
static int printed_flag = 0;

static void maybe_print_space(void)
{
    if (printed_flag) {
        putchar(' ');
    } else {
        printed_flag = 1;
    }
}

/* Traversal functions – they mimic the original’s exact output format. */
static void inorder(Node *n)
{
    if (n == NULL) return;
    inorder(n->left);
    maybe_print_space();
    printf("%ld", n->value);
    inorder(n->right);
}

static void preorder(Node *n)
{
    if (n == NULL) return;
    maybe_print_space();
    printf("%ld", n->value);
    preorder(n->left);
    preorder(n->right);
}

static void postorder(Node *n)
{
    if (n == NULL) return;
    postorder(n->left);
    postorder(n->right);
    maybe_print_space();
    printf("%ld", n->value);
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* The original binary required at least one argument after the program name. */
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    const char *mode = argv[1];
    int valid_mode = (strcmp(mode, "in") == 0) ||
                     (strcmp(mode, "pre") == 0) ||
                     (strcmp(mode, "post") == 0);

    if (!valid_mode) {
        puts("INVALID_MODE");
        return 0;
    }

    /* Build the BST from the remaining arguments. */
    Node *root = NULL;
    for (int i = 2; i < argc; ++i) {
        char *endptr = NULL;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;   /* ignore conversion errors – same as original */
        bst_insert(&root, v);
    }

    /* If the tree is empty, print "EMPTY". */
    if (root == NULL) {
        puts("EMPTY");
        return 0;
    }

    printed_flag = 0;   /* reset before traversal */

    if (strcmp(mode, "in") == 0) {
        inorder(root);
    } else if (strcmp(mode, "pre") == 0) {
        preorder(root);
    } else { /* mode == "post" */
        postorder(root);
    }

    putchar('\n');
    return 0;
}
